/**
 * Interactive Admitted Students from Other States Map Card
 */
export function AdmittedStudentsMapCard({
  selectedDistrict,
  onSelectDistrict,
}: {
  selectedDistrict: DistrictMapItem | null;
  onSelectDistrict: (district: DistrictMapItem | null) => void;
}) {
  const [hoveredDistrict, setHoveredDistrict] = useState<DistrictMapItem | null>(null);

  const formatNumber = (num: number) => num.toLocaleString("en-IN");
  const activeDistrict = selectedDistrict ?? hoveredDistrict;
  const totalOutsideStudents = WB_DISTRICTS.reduce((acc, curr) => acc + curr.count, 0);

  return (
    <div className="bg-slate-50/40 hover:bg-[#e9f2fc] rounded-3xl border border-slate-100 hover:border-blue-200/60 shadow-soft transition-all duration-300 p-6 flex flex-col gap-4 w-full relative min-h-[580px]">
      {/* Header */}
      <div className="border-b border-slate-100 pb-3 flex justify-between items-center z-10">
        <div>
          <h3 className="text-base font-extrabold text-brand-900 tracking-tight">
            Admitted Students from Other States
          </h3>
          <p className="text-xs text-slate-500 font-medium">
            District-wise concentration of students enrolled from outside West Bengal
          </p>
        </div>
        <div className="flex items-center gap-2">
          {selectedDistrict && (
            <button
              onClick={() => onSelectDistrict(null)}
              className="flex items-center gap-1 text-xs bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold px-2.5 py-1 rounded-full transition-colors cursor-pointer"
            >
              <X size={12} />
              Reset Filter
            </button>
          )}
          <span className="text-xs bg-blue-100/80 text-blue-700 font-bold px-3 py-1 rounded-full uppercase tracking-wider border border-blue-200">
            Total: {formatNumber(totalOutsideStudents)}
          </span>
        </div>
      </div>

      {/* SVG Map Canvas */}
      <div className="flex-1 w-full relative flex items-center justify-center py-2">
        <svg
          viewBox="0 0 480 680"
          className="w-full max-w-[430px] h-auto select-none"
          style={{ filter: "drop-shadow(0 6px 18px rgba(37,99,235,0.12))" }}
        >
          {/* District Polygons */}
          <g>
            {WB_DISTRICTS.map((dist) => {
              const isHovered = hoveredDistrict?.id === dist.id;
              const isSelected = selectedDistrict?.id === dist.id;
              const isActive = isHovered || isSelected;
              const isDimmed = selectedDistrict !== null && !isSelected;

              return (
                <path
                  key={dist.id}
                  d={dist.d}
                  fill={isActive ? "#2563eb" : isDimmed ? "#f1f5f9" : "#e0effe"}
                  stroke={isActive ? "#1d4ed8" : "#93c5fd"}
                  strokeWidth={isActive ? 1.8 : 0.8}
                  strokeLinejoin="round"
                  strokeLinecap="round"
                  className="cursor-pointer transition-colors duration-200 ease-out"
                  onMouseEnter={() => setHoveredDistrict(dist)}
                  onMouseLeave={() => setHoveredDistrict(null)}
                  onClick={() => onSelectDistrict(selectedDistrict?.id === dist.id ? null : dist)}
                />
              );
            })}
          </g>

          {/* District Center Markers & Labels */}
          <g className="pointer-events-none">
            {WB_DISTRICTS.map((dist) => {
              const isHovered = hoveredDistrict?.id === dist.id;
              const isSelected = selectedDistrict?.id === dist.id;
              const isActive = isHovered || isSelected;

              return (
                <g key={`marker-${dist.id}`}>
                  {/* Pulsing Beacon Dot */}
                  <circle
                    cx={dist.cx}
                    cy={dist.cy}
                    r={isActive ? 4.5 : 3}
                    fill={isActive ? "#ffffff" : "#1d4ed8"}
                    stroke={isActive ? "#1d4ed8" : "#ffffff"}
                    strokeWidth={1.5}
                    style={{ filter: "drop-shadow(0 1px 3px rgba(0,0,0,0.25))" }}
                  />

                  {/* District Name Label */}
                  <text
                    x={dist.cx}
                    y={dist.cy - 7}
                    textAnchor="middle"
                    className="select-none font-bold tracking-tight"
                    style={{
                      fontSize: isActive ? "10px" : "7.5px",
                      fill: isActive ? "#0f172a" : "#1e3a8a",
                      fontWeight: isActive ? 900 : 700,
                      paintOrder: "stroke",
                      stroke: "#ffffff",
                      strokeWidth: "2.5px",
                      strokeLinejoin: "round",
                      transition: "all 0.15s ease",
                    }}
                  >
                    {dist.name}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>

        {/* Dynamic Detail Card overlay */}
        {activeDistrict && (
          <div className="absolute top-4 right-4 bg-white/95 backdrop-blur-md border border-blue-200/90 shadow-2xl rounded-2xl p-4 text-brand-900 w-64 select-none z-30 animate-fadeIn">
            <div className="flex items-center justify-between border-b border-slate-100 pb-2 mb-2">
              <span className="text-[11px] font-extrabold text-blue-600 uppercase tracking-wider flex items-center gap-1">
                <Globe2 size={14} />
                Outside-State Admissions
              </span>
              <span className="text-[10px] text-slate-400 font-bold">WB</span>
            </div>

            <h4 className="text-base font-black text-brand-950 mb-2">
              {activeDistrict.name}
            </h4>

            <div className="space-y-1.5 text-xs">
              <div className="bg-blue-50/80 rounded-xl p-2.5 flex items-baseline justify-between border border-blue-100">
                <span className="font-semibold text-slate-600 flex items-center gap-1">
                  <Users size={12} className="text-blue-600" /> Outside Students:
                </span>
                <span className="text-base font-black text-blue-700">
                  {formatNumber(activeDistrict.count)}
                </span>
              </div>

              <div className="grid grid-cols-2 gap-1.5 pt-0.5">
                <div className="bg-pink-50/70 rounded-lg p-1.5 text-center border border-pink-100">
                  <span className="text-[10px] text-pink-700 font-bold block">Female</span>
                  <span className="text-xs font-black text-slate-800">{formatNumber(activeDistrict.female)}</span>
                </div>
                <div className="bg-blue-50/70 rounded-lg p-1.5 text-center border border-blue-100">
                  <span className="text-[10px] text-blue-700 font-bold block">Male</span>
                  <span className="text-xs font-black text-slate-800">{formatNumber(activeDistrict.male)}</span>
                </div>
              </div>

              <div className="bg-slate-50 rounded-lg p-2 text-[11px] text-slate-600 border border-slate-100 mt-1">
                <span className="font-bold text-slate-500 block text-[10px] uppercase tracking-wider">Top Origin States:</span>
                <span className="font-extrabold text-brand-950">{activeDistrict.topOrigin}</span>
              </div>
            </div>

            <p className="text-[10px] text-blue-600 font-bold mt-2.5 text-center bg-blue-50/60 py-1 rounded-lg">
              {selectedDistrict?.id === activeDistrict.id ? "✓ District locked — waiver chart synced" : "Click district to filter fee waiver graph"}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Dynamic Fee Waiver Impact Chart synchronized with Map Selection
 */
export function FeeWaiverImpactChartCard({
  selectedDistrict,
  onResetDistrict,
}: {
  selectedDistrict: DistrictMapItem | null;
  onResetDistrict?: () => void;
}) {
  const [hoveredYear, setHoveredYear] = useState<number | null>(null);

  const formatNumber = (num: number) => num.toLocaleString("en-IN");

  const years = ["2022-23", "2023-24", "2024-25", "2025-26"];

  const activeData = selectedDistrict ? selectedDistrict.feeWaiver : ALL_BENGAL_TOTALS.feeWaiver;
  const displayName = selectedDistrict ? selectedDistrict.name : "All West Bengal";

  const ewsValues = activeData.ews;
  const obcValues = activeData.obc;
  const sebcValues = activeData.sebc;

  // Maximum value for dynamic scaling of Y-axis
  const maxVal = Math.max(
    ...ewsValues,
    ...obcValues,
    ...(sebcValues.filter((v): v is number => v !== null))
  );

  const yCeil = Math.ceil(maxVal * 1.15 / 1000) * 1000 || 60000;
  const yStep = Math.round(yCeil / 3);

  const getYPos = (val: number | null) => {
    if (val === null) return 215;
    return 215 - (val / yCeil) * 180;
  };

  const getObcPoints = () =>
    obcValues.map((v, i) => `${60 + i * 133.33},${getYPos(v).toFixed(2)}`).join(" ");

  const getSebcPoints = () =>
    sebcValues
      .map((v, i) => (v !== null ? `${60 + i * 133.33},${getYPos(v).toFixed(2)}` : null))
      .filter(Boolean)
      .join(" ");

  const getEwsPoints = () =>
    ewsValues.map((v, i) => `${60 + i * 133.33},${getYPos(v).toFixed(2)}`).join(" ");

  return (
    <div className="bg-[#fdf2f8] hover:bg-[#fbcfe8] rounded-3xl border border-pink-200/40 hover:border-pink-300 shadow-soft transition-all duration-300 p-6 flex flex-col gap-4 w-full relative min-h-[580px]">
      {/* Header */}
      <div className="border-b border-slate-100 pb-3 flex flex-col md:flex-row md:justify-between md:items-center gap-2 z-10">
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-base font-extrabold text-brand-900 tracking-tight">
              Impact of Fee Waiver in Professional Courses for Females
            </h3>
          </div>
          <p className="text-xs text-slate-500 font-medium flex items-center gap-1.5 mt-0.5">
            <TrendingUp size={13} className="text-pink-600" />
            <span>Scope:</span>
            <span className="font-black text-pink-700 bg-pink-100/80 px-2 py-0.5 rounded-md">
              {displayName}
            </span>
            {selectedDistrict && onResetDistrict && (
              <button
                onClick={onResetDistrict}
                className="text-[10px] font-bold text-slate-500 hover:text-slate-800 underline ml-1 cursor-pointer"
              >
                (View All Bengal)
              </button>
            )}
          </p>
        </div>

        {/* Legend */}
        <div className="flex items-center gap-4 text-xs font-black text-slate-700 flex-wrap">
          <span className="text-slate-400 font-bold uppercase tracking-wider text-[10px]">Category</span>
          <span className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-[#3b82f6]" /> EWS
          </span>
          <span className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-[#1d4ed8]" /> OBC
          </span>
          <span className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-[#f97316]" /> SEBC
          </span>
        </div>
      </div>

      {/* SVG Container for the Line Chart */}
      <div className="relative w-full h-[380px] flex items-center justify-center mt-2 select-none">
        <svg viewBox="0 0 500 250" className="w-full h-full">
          {/* Horizontal Gridlines */}
          <line x1="60" y1="215" x2="460" y2="215" stroke="#e2e8f0" strokeWidth="1.5" />
          <line x1="60" y1="155" x2="460" y2="155" stroke="#f1f5f9" strokeWidth="1" strokeDasharray="3 3" />
          <line x1="60" y1="95" x2="460" y2="95" stroke="#f1f5f9" strokeWidth="1" strokeDasharray="3 3" />
          <line x1="60" y1="35" x2="460" y2="35" stroke="#f1f5f9" strokeWidth="1" strokeDasharray="3 3" />

          {/* Y-axis Labels */}
          <text x="50" y="218" textAnchor="end" className="text-[10px] font-bold fill-slate-400">0</text>
          <text x="50" y="158" textAnchor="end" className="text-[10px] font-bold fill-slate-400">
            {yStep >= 1000 ? `${(yStep / 1000).toFixed(0)}K` : yStep}
          </text>
          <text x="50" y="98" textAnchor="end" className="text-[10px] font-bold fill-slate-400">
            {yStep * 2 >= 1000 ? `${((yStep * 2) / 1000).toFixed(0)}K` : yStep * 2}
          </text>
          <text x="50" y="38" textAnchor="end" className="text-[10px] font-bold fill-slate-400">
            {yCeil >= 1000 ? `${(yCeil / 1000).toFixed(0)}K` : yCeil}
          </text>

          {/* Y-axis Title */}
          <text x="18" y="125" textAnchor="middle" transform="rotate(-90 18 125)" className="text-[10px] font-black fill-slate-500 uppercase tracking-wider">
            Female Beneficiaries
          </text>

          {/* X-axis Labels */}
          <text x="60" y="235" textAnchor="middle" className="text-[11px] font-black fill-slate-700">2022-23</text>
          <text x="193.33" y="235" textAnchor="middle" className="text-[11px] font-black fill-slate-700">2023-24</text>
          <text x="326.67" y="235" textAnchor="middle" className="text-[11px] font-black fill-slate-700">2024-25</text>
          <text x="460" y="235" textAnchor="middle" className="text-[11px] font-black fill-slate-700">2025-26</text>

          {/* Line: OBC (Dark Blue) */}
          <polyline
            fill="none"
            stroke="#1d4ed8"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            points={getObcPoints()}
            className="transition-all duration-500"
          />
          {obcValues.map((v, i) => (
            <g key={`obc-pt-${i}`}>
              <circle
                cx={60 + i * 133.33}
                cy={getYPos(v)}
                r="4.5"
                fill="#1d4ed8"
                stroke="white"
                strokeWidth="1.5"
                className="transition-all duration-500"
              />
              <text
                x={60 + i * 133.33}
                y={getYPos(v) - 8}
                textAnchor="middle"
                className="text-[10.5px] font-extrabold fill-[#1d4ed8]"
              >
                {formatNumber(v)}
              </text>
            </g>
          ))}

          {/* Line: SEBC (Orange) */}
          <polyline
            fill="none"
            stroke="#f97316"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            points={getSebcPoints()}
            className="transition-all duration-500"
          />
          {sebcValues.map((v, i) =>
            v !== null ? (
              <g key={`sebc-pt-${i}`}>
                <circle
                  cx={60 + i * 133.33}
                  cy={getYPos(v)}
                  r="4.5"
                  fill="#f97316"
                  stroke="white"
                  strokeWidth="1.5"
                  className="transition-all duration-500"
                />
                <text
                  x={60 + i * 133.33}
                  y={getYPos(v) - 8}
                  textAnchor="middle"
                  className="text-[10.5px] font-extrabold fill-[#f97316]"
                >
                  {formatNumber(v)}
                </text>
              </g>
            ) : null
          )}

          {/* Line: EWS (Light Blue) */}
          <polyline
            fill="none"
            stroke="#3b82f6"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            points={getEwsPoints()}
            className="transition-all duration-500"
          />
          {ewsValues.map((v, i) => (
            <g key={`ews-pt-${i}`}>
              <circle
                cx={60 + i * 133.33}
                cy={getYPos(v)}
                r="4.5"
                fill="#3b82f6"
                stroke="white"
                strokeWidth="1.5"
                className="transition-all duration-500"
              />
              <text
                x={60 + i * 133.33}
                y={getYPos(v) + 14}
                textAnchor="middle"
                className="text-[10px] font-extrabold fill-[#3b82f6]"
              >
                {formatNumber(v)}
              </text>
            </g>
          ))}

          {/* Hover highlight line */}
          {hoveredYear !== null && (
            <g>
              <line
                x1={60 + hoveredYear * 133.33}
                y1="35"
                x2={60 + hoveredYear * 133.33}
                y2="215"
                stroke="#64748b"
                strokeWidth="1.5"
                strokeDasharray="3 3"
              />
            </g>
          )}

          {/* Interactive Click/Hover Columns */}
          {[0, 1, 2, 3].map((i) => (
            <rect
              key={`col-${i}`}
              x={40 + i * 133.33}
              y="30"
              width="45"
              height="190"
              fill="transparent"
              className="cursor-pointer"
              onMouseEnter={() => setHoveredYear(i)}
              onMouseLeave={() => setHoveredYear(null)}
            />
          ))}
        </svg>
      </div>
    </div>
  );
}

/**
 * Combined Section managing synchronization between Map and Fee Waiver Chart
 */
export function WestBengalAdmissionsSection({
  academicYear = "2025-26",
  globalFilters,
  onDistrictChange
}: {
  academicYear?: string;
  globalFilters?: any;
  onDistrictChange?: (district: DistrictMapItem | null) => void;
}) {
  // Determine district to select if university/college is filtered
  const targetDistrictId = (() => {
    if (!globalFilters?.university || globalFilters.university === "All") return null;
    const u = globalFilters.university.toUpperCase();
    if (["CU", "JU", "PRESIDENCY", "ALIAH", "RBU"].includes(u)) return "kolkata";
    if (u === "BU") return "purba_bardhaman";
    if (u === "WBSU") return "north_twenty_four_parganas";
    if (u === "KU") return "nadia";
    if (u === "VU") return "paschim_medinipur";
    if (u === "NBU") return "darjeeling";
    if (u === "UGB") return "maldah";
    if (u === "KNU") return "paschim_bardhaman";
    if (u === "SKBU") return "purulia";
    if (u === "BKU") return "bankura";
    if (u === "CBPBU") return "coochbehar";
    if (u.includes("VISVA")) return "birbhum";
    return null;
  })();

  const defaultDistrict = targetDistrictId
    ? (WB_DISTRICTS.find(d => d.id === targetDistrictId || d.id.includes(targetDistrictId) || targetDistrictId.includes(d.id)) || null)
    : null;

  const [selectedDistrict, setSelectedDistrict] = useState<DistrictMapItem | null>(defaultDistrict);

  // Sync selected district when globalFilters university changes
  React.useEffect(() => {
    setSelectedDistrict(defaultDistrict);
    onDistrictChange?.(defaultDistrict);
  }, [targetDistrictId]);

  const handleSelectDistrict = (district: DistrictMapItem | null) => {
    setSelectedDistrict(district);
    onDistrictChange?.(district);
  };

  return (
    <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 w-full mt-6">
      <AdmittedStudentsMapCard
        selectedDistrict={selectedDistrict}
        onSelectDistrict={handleSelectDistrict}
      />
      <FeeWaiverImpactChartCard
        selectedDistrict={selectedDistrict}
        onResetDistrict={() => handleSelectDistrict(null)}
      />
    </div>
  );
}
